/**
 * Provider logos for the model picker and wherever a provider shows, ported from T3 Code (MIT):
 * `apps/web/src/components/Icons.tsx` and the `icon` in each provider package `src/client.ts`.
 * Generated by the models lane's `gen_logos.py` from T3's own path data.
 *
 * One colour (`currentColor`), like every mark on the agents surface (`brand-icons.tsx`): roll
 * never uses orange, so Claude's mark is not in its brand colour. A second-tone shape (OpenCode's
 * inner square) is drawn at lower opacity. Gemini's four-point star is drawn here; T3 has no mark
 * for Gemini CLI (its Gemini models come through Antigravity, a bitmap).
 */

import type { SVGProps } from "react";
import type { Glyph } from "./brand-icons";

type Props = Omit<SVGProps<SVGSVGElement>, "strokeWidth"> & { strokeWidth?: number | string };

interface Shape {
  d: string;
  evenodd?: boolean;
  /** A second tone, drawn lighter. */
  tone?: boolean;
}

const logo = (viewBox: string, shapes: Shape[]) =>
  function Logo({ strokeWidth: _s, ...props }: Props) {
    return (
      <svg viewBox={viewBox} fill="currentColor" aria-hidden preserveAspectRatio="xMidYMid meet" {...props}>
        {shapes.map((s, i) => (
          <path key={i} d={s.d} fillRule={s.evenodd ? "evenodd" : undefined} clipRule={s.evenodd ? "evenodd" : undefined} opacity={s.tone ? 0.4 : undefined} />
        ))}
      </svg>
    );
  };

